INSERT INTO documents_api_schema
  (id, tenant_id, surface_id, schema_version, spec, schema_checksum, source_path, imported_at)
VALUES
  ('8c97166b-c89a-5223-8cc0-a669dca4e284', 100001, 'cdc9c963-6e43-55a1-8185-24ba4ff270d6', '0.1.0', $sdkwork_catalog${"components":{"schemas":{"AbortProviderObjectMultipartUploadRequest":{"additionalProperties":false,"properties":{"objectKey":{"description":"Drive object listing key. UTF-8 1-1024 bytes, trimmed relative key; no leading slash, double slash, NUL, or period-only path segments.","maxLength":1024,"minLength":1,"pattern":"^(?!/)(?!.*//)(?!.*(?:^|/)\\.{1,2}(?:/|$))(?!.*\\u0000).+$","type":"string"},"uploadId":{"description":"Opaque vendor multipart upload id returned by `...multipartUpload.create`. It is never parsed, only echoed back to the vendor.","maxLength":2048,"minLength":1,"type":"string"}},"required":["objectKey","uploadId"],"type":"object"},"CompleteProviderObjectMultipartUploadRequest":{"additionalProperties":false,"properties":{"objectKey":{"description":"Drive object listing key. UTF-8 1-1024 bytes, trimmed relative key; no leading slash, double slash, NUL, or period-only path segments.","maxLength":1024,"minLength":1,"pattern":"^(?!/)(?!.*//)(?!.*(?:^|/)\\.{1,2}(?:/|$))(?!.*\\u0000).+$","type":"string"},"parts":{"items":{"$ref":"#/components/schemas/ProviderObjectUploadPartReference"},"maxItems":10000,"minItems":1,"type":"array"},"uploadId":{"description":"Opaque vendor multipart upload id returned by `...multipartUpload.create`. It is never parsed, only echoed back to the vendor.","maxLength":2048,"minLength":1,"type":"string"}},"required":["objectKey","uploadId","parts"],"type":"object"},"CopyProviderObjectRequest":{"additionalProperties":false,"properties":{"destinationBucket":{"description":"S3-compatible bucket name. DNS-compatible 3-63 characters; lowercase letters, digits, dots, and hyphens only; must start and end with a letter or digit; no IPv4-looking names, adjacent dots, dot-hyphen adjacency, or reserved S3 affixes.","maxLength":63,"minLength":3,"pattern":"^(?!xn--)(?!sthree-)(?!.*\\.\\.)(?!.*\\.-)(?!.*-\\.)(?!\\d+\\.\\d+\\.\\d+\\