  ('1f5fb8c9-b936-507b-bb34-96dd8de82b54', 100001, 'cdc9c963-6e43-55a1-8185-24ba4ff270d6', 'storageProviders.test', 'POST', '/backend/v3/api/drive/storage/providers/{providerId}/test', '', '', $sdkwork_catalog$["storageAdmin"]$sdkwork_catalog$::jsonb, FALSE, 130),
  ('aede5282-2c27-5208-a6e5-f050bb53a1d8', 100001, 'cdc9c963-6e43-55a1-8185-24ba4ff270d6', 'storageProviders.bucket.retrieve', 'GET', '/backend/v3/api/drive/storage/providers/{providerId}/bucket', '', '', $sdkwork_catalog$["storageAdmin"]$sdkwork_catalog$::jsonb, FALSE, 140),
  ('69211182-83e2-58a7-bb76-250a5a4f758f', 100001, 'cdc9c963-6e43-55a1-8185-24ba4ff270d6', 'storageProviders.bucket.update', 'PUT', '/backend/v3/api/drive/storage/providers/{providerId}/bucket', 'Initialize storage bucket', 'Idempotent bucket initialization: ensures the provider’s configured bucket exists on its vendor, creating it only when missing. Re-running the operation converges (response changed=false) instead of failing with vendor-specific "already exists" errors, so initialization can be replayed after configuration changes or bucket deletion. Supported for every provider kind that exposes an object store (S3-compatible vendors and the local filesystem store).', $sdkwork_catalog$["storageAdmin"]$sdkwork_catalog$::jsonb, FALSE, 150),
  ('96c74ad6-6411-5572-b83f-31a42049e676', 100001, 'cdc9c963-6e43-55a1-8185-24ba4ff270d6', 'storageProviders.bucket.delete', 'DELETE', '/backend/v3/api/drive/storage/providers/{providerId}/bucket', '', '', $sdkwork_catalog$["storageAdmin"]$sdkwork_catalog$::jsonb, FALSE, 160),
  ('f88f76c6-0efe-5250-a92f-016a2bd0b1f8', 100001, 'cdc9c963-6e43-55a1-8185-24ba4ff270d6', 'storageProviders.objects.list', 'GET', '/backend/v3/api/drive/storage/providers/{providerId}/objects', '', '', $sdkwork_catalog$["storageAdmin"]$sdkwork_catalog$::jsonb, FALSE, 170),
  ('99fec596-4c60-5899-9c63-9bf653e028e7', 100001, 'cdc9c963-6e43-55a1-8185-24ba4ff270d6', 'storageProviders.objects.retrieve', 'GET', '/backend/v3/api/drive/storage/providers/{providerId}/objects/{objectKey}', '', '', $sdkwork_catalog$["storageAdmin"]$sdkwork_catalog$::jsonb, FALSE, 180),
  ('ed4e9fbb-3275-5aa1-9545-71b9ce4e4e70', 100001, 'cdc9c963-6e43-55a1-8185-24ba4ff270d6', 'storageProviders.objects.delete', 'DELETE', '/backend/v3/api/drive/storage/providers/{providerId}/objects/{objectKey}', '', '', $sdkwork_catalog$["storageAdmin"]$sdkwork_catalog$::jsonb, FALSE, 190),
  ('a5087bf6-8195-5ea5-b6ad-b086ddfb59b3', 100001, 'cdc9c963-6e43-55a1-8185-24ba4ff270d6', 'storageProviders.objects.copy', 'POST', '/backend/v3/api/drive/storage/providers/{providerId}/objects/copy', '', '', $sdkwork_catalog$["storageAdmin"]$sdkwork_catalog$::jsonb, FALSE, 200),
  ('96c57028-18c4-5582-86b3-5bdd8d50b899', 100001, 'cdc9c963-6e43-55a1-8185-24ba4ff270d6', 'storageProviders.objects.multipartUpload.create', 'POST', '/backend/v3/api/drive/storage/providers/{providerId}/objects/multipart-uploads', 'Start a provider object multipart upload', 'Opens a vendor multipart upload for one object key and returns its uploadId. Use it for objects above the single-request content limit (8 MiB): the browser uploads each part straight to the vendor with the presigned URLs from `storageProviders.objects.multipartUpload.parts.presign`, then calls `...complete`. Abandoned uploads hold billable parts until `...abort` runs.', $sdkwork_catalog$["storageAdmin"]$sdkwork_catalog$::jsonb, FALSE, 210),
  ('fc7d84e1-cac8-5cda-b016-97d20930a4ef', 100001, 'cdc9c963-6e43-55a1-8185-24ba4ff270d6', 'storageProviders.objects.multipartUpload.parts.presign', 'POST', '/backend/v3/api/drive/storage/providers/{providerId}/objects/multipart-uploads/parts', 'Presign provider object upload parts', 'Returns one presigned PUT grant per requested part number. The client must send the returned `headers` verbatim: they are part of the signature (server-side encryption and content type are signed too). The vendor bucket must allow cross-origin PUT from the console origin and expose the `ETag` response header, otherwise the browser cannot report part ETags and `...complete` cannot succeed.', $sdkwork_catalog$["storageAdmin"]$sdkwork_catalog$::jsonb, FALSE, 220),
  ('35ebfd83-4e73-56c2-8e7c-b2bd7ce96efb', 100001, 'cdc9c963-6e43-55a1-8185-24ba4ff270d6', 'storageProviders.objects.multipartUpload.complete', 'POST', '/backend/v3/api/drive/storage/providers/{providerId}/objects/multipart-uploads/complete', 'Complete a provider object multipart upload', 'Finishes the multipart upload from the collected part ETags and returns the written object. Part numbers must be the ones that were uploaded, each with the ETag the vendor returned for that part.', $sdkwork_catalog$["storageAdmin"]$sdkwork_catalog$::jsonb, FALSE, 230),
  ('2b82ec6d-e183-56d6-9dd8-4300ea70c9ef', 100001, 'cdc9c963-6e43-55a1-8185-24ba4ff270d6', 'storageProviders.objects.multipartUpload.abort', 'POST', '/backend/v3/api/drive/storage/providers/{providerId}/objects/multipart-uploads/abort', 'Abort a provider object multipart upload', 'Discards an in-flight multipart upload. Call it when the operator cancels or closes the upload, so the vendor does not keep billing for the parts already uploaded.', $sdkwork_catalog$["storageAdmin"]$sdkwork_catalog$::jsonb, FALSE, 240),
  ('d225856a-f52e-5197-b6a8-124abd059b76', 100001, 'cdc9c963-6e43-55a1-8185-24ba4ff270d6', 'storageProviders.buckets.list', 'GET', '/backend/v3/api/drive/storage/providers/{providerId}/buckets', 'List buckets visible to a Drive storage provider account', '', $sdkwork_catalog$["storageAdmin"]$sdkwork_catalog$::jsonb, FALSE, 250),
  ('229a1115-ab1f-5b50-ad21-d6bd9a736bc4', 100001, 'cdc9c963-6e43-55a1-8185-24ba4ff270d6', 'storageProviderBindings.list', 'GET', '/backend/v3/api/drive/storage/bindings', 'List Drive storage provider bindings', 'List storage bindings, ordered by resolution priority (space, then space type, then tenant). Filter with `binding_scope` when the caller renders one resolution step at a time: the unfiltered list is a single page window over every step, so enough space-scoped bindings push the space-type rows past it.', $sdkwork_catalog$["storageAdmin"]$sdkwork_catalog$::jsonb, FALSE, 260),
  ('e6f567c2-6626-5b56-b444-b3682481f383', 100001, 'cdc9c963-6e43-55a1-8185-24ba4ff270d6', 'storageProviderKinds.list', 'GET', '/backend/v3/api/drive/storage/provider-kinds', '', '', $sdkwork_catalog$["storageAdmin"]$sdkwork_catalog$::jsonb, FALSE, 270),
  ('700584de-8194-51ca-8770-653d50cb3135', 100001, 'cdc9c963-6e43-55a1-8185-24ba4ff270d6', 'storageProviderKinds.create', 'POST', '/backend/v3/api/drive/storage/provider-kinds', '', '', $sdkwork_catalog$["storageAdmin"]$sdkwork_catalog$::jsonb, FALSE, 280),
  ('5ad4b106-5263-55d0-b552-aff96254c5e1', 100001, 'cdc9c963-6e43-55a1-8185-24ba4ff270d6', 'storageProviderKinds.update', 'PATCH', '/backend/v3/api/drive/storage/provider-kinds/{providerKind}', '', '', $sdkwork_catalog$["storageAdmin"]$sdkwork_catalog$::jsonb, FALSE, 290),
  ('ffbbdca8-1024-5961-831e-0f4269fb46a7', 100001, 'cdc9c963-6e43-55a1-8185-24ba4ff270d6', 'storageProviders.objects.content.retrieve', 'GET', '/backend/v3/api/drive/storage/providers/{providerId}/object-contents/{objectKey}', 'Retrieve provider object content', 'Reads a single provider object up to 8 MiB. Larger objects must use the presigned download channel. Content is returned base64-encoded with size and SHA-256 checksum.', $sdkwork_catalog$["storageAdmin"]$sdkwork_catalog$::jsonb, FALSE, 300),
  ('97e7f8c4-be32-5f0d-ba69-58a5261e4bf2', 100001, 'cdc9c963-6e43-55a1-8185-24ba4ff270d6', 'storageProviders.objects.content.update', 'PUT', '/backend/v3/api/drive/storage/providers/{providerId}/object-contents/{objectKey}', 'Write provider object content', 'Creates or replaces a provider object. encoding is utf8 (default) or base64. An object key ending with a slash and empty content creates a directory placeholder.', $sdkwork_catalog$["storageAdmin"]$sdkwork_catalog$::jsonb, FALSE, 310),
  ('5756f962-7cd2-5392-bfcd-e106e8295e8b', 100001, 'cdc9c963-6e43-55a1-8185-24ba4ff270d6', 'storageProviderAccounts.list', 'GET', '/backend/v3/api/drive/storage/provider-accounts', '', '', $sdkwork_catalog$["storageAdmin"]$sdkwork_catalog$::jsonb, FALSE, 320),
  ('a59f7800-c4e3-5832-88ae-851ae93360f2', 100001, 'cdc9c963-6e43-55a1-8185-24ba4ff270d6', 'storageProviderAccounts.create', 'POST', '/backend/v3/api/drive/storage/provider-accounts', '', '', $sdkwork_catalog$["storageAdmin"]$sdkwork_catalog$::jsonb, FALSE, 330),
  ('f76f5a30-c498-5119-bf41-3eb20981e2c9', 100001, 'cdc9c963-6e43-55a1-8185-24ba4ff270d6', 'storageProviderAccountDefaults.create', 'POST', '/backend/v3/api/drive/storage/provider-account-defaults', '', '', $sdkwork_catalog$["storageAdmin"]$sdkwork_catalog$::jsonb, FALSE, 340),
  ('c9556220-2ec2-527c-b056-d8de01916b84', 100001, 'cdc9c963-6e43-55a1-8185-24ba4ff270d6', 'storageOverview.retrieve', 'GET', '/backend/v3/api/drive/storage/overview', 'Retrieve the Drive storage overview', 'Aggregated read-only statistics for the storage center dashboard: tenant capacity and growth, provider inventory and per-provider usage, binding health, and provider catalog coverage. Capacity, usage and binding figures are tenant-scoped; the provider catalog is platform-wide because dr_drive_storage_provider_kind carries no tenant dimension.', $sdkwork_catalog$["storageAdmin"]$sdkwork_catalog$::jsonb, FALSE, 350),
  ('9ccea831-1498-5600-abc8-dbeb6e7a3397', 100001, 'cdc9c963-6e43-55a1-8185-24ba4ff270d6', 'storageMigrations.list', 'GET', '/backend/v3/api/drive/storage/migrations', '', '', $sdkwork_catalog$["storageAdmin"]$sdkwork_catalog$::jsonb, FALSE, 360),
  ('b77ae5b0-cbe8-512d-9625-7b774935c0a8', 100001, 'cdc9c963-6e43-55a1-8185-24ba4ff270d6', 'storageMigrations.create', 'POST', '/backend/v3/api/drive/storage/migrations', '', '', $sdkwork_catalog$["storageAdmin"]$sdkwork_catalog$::jsonb, FALSE, 370),
  ('70c12b33-ebbb-52e5-b9b5-0a982c71d653', 100001, 'cdc9c963-6e43-55a1-8185-24ba4ff270d6', 'storageMigrations.retrieve', 'GET', '/backend/v3/api/drive/storage/migrations/{migrationId}', '', '', $sdkwork_catalog$["storageAdmin"]$sdkwork_catalog$::jsonb, FALSE, 380),
  ('05947906-223b-53a1-8cd3-2e1f417c49b4', 100001, 'cdc9c963-6e43-55a1-8185-24ba4ff270d6', 'storageMigrations.run', 'POST', '/backend/v3/api/drive/storage/migrations/{migrationId}/run', '', '', $sdkwork_catalog$["storageAdmin"]$sdkwork_catalog$::jsonb, FALSE, 390),
  ('59ec7fc3-53da-51bb-88ed-e76306390d4a', 100001, 'cdc9c963-6e43-55a1-8185-24ba4ff270d6', 'storageMigrations.items.list', 'GET', '/backend/v3/api/drive/storage/migrations/{migrationId}/items', '', '', $sdkwork_catalog$["storageAdmin"]$sdkwork_catalog$::jsonb, FALSE, 400),
  ('c1f309ec-9405-5d5a-b8d0-03e91ea588dc', 100001, 'cdc9c963-6e43-55a1-8185-24ba4ff270d6', 'storageMigrations.cancel', 'POST', '/backend/v3/api/drive/storage/migrations/{migrationId}/cancel', '', '', $sdkwork_catalog$["storageAdmin"]$sdkwork_catalog$::jsonb, FALSE, 410)
