VALUES
  ('bb9516fb-3921-5113-a629-b9b4a4a7d7d6', 100001, 'b45c8351-d439-5d6b-98e9-cfe2dcc55ccb', 'rootScopeSubscriptions.create', 'POST', '/internal/v3/api/drive/root_scope_subscriptions', 'Register a Knowledgebase sources/raw root scope', '', $sdkwork_catalog$["driveInternalPublishing"]$sdkwork_catalog$::jsonb, FALSE, 10),
  ('8b76a022-e547-569c-a010-3d746b6a54e1', 100001, 'b45c8351-d439-5d6b-98e9-cfe2dcc55ccb', 'rootScopeSubscriptions.retrieve', 'GET', '/internal/v3/api/drive/root_scope_subscriptions/{subscriptionUuid}', 'Retrieve a root scope subscription', '', $sdkwork_catalog$["driveInternalPublishing"]$sdkwork_catalog$::jsonb, FALSE, 20),
  ('cd9d2049-c1e8-5ae5-9d9d-0f220ab3a3e0', 100001, 'b45c8351-d439-5d6b-98e9-cfe2dcc55ccb', 'rootScopeEventDeliveries.replace', 'PUT', '/internal/v3/api/drive/root_scope_subscriptions/{subscriptionUuid}/event_delivery', 'Ensure the signed Knowledgebase event delivery channel for a root scope', 'Creates or replaces the deterministic Drive-to-Knowledgebase webhook channel for a root scope. The verification token is write-only and is never returned or logged. Drive stores only its SHA-256 derived signing key and signs the exact event body bytes.', $sdkwork_catalog$["driveInternalPublishing"]$sdkwork_catalog$::jsonb, FALSE, 30),
  ('994909de-af25-5d31-829a-f6d0dad55262', 100001, 'b45c8351-d439-5d6b-98e9-cfe2dcc55ccb', 'websiteRoots.retrieve', 'GET', '/internal/v3/api/drive/website_roots/{websiteRootUuid}', 'Retrieve a website delivery root', 'Returns the tenant-scoped WebsiteRoot lifecycle, generation, selection mode, and delivery capabilities required by trusted website runtimes. Drive node identities, selected folder identities, object-store coordinates, credentials, and presigned URLs never cross this boundary.', $sdkwork_catalog$["driveInternalPublishing"]$sdkwork_catalog$::jsonb, FALSE, 40),
  ('22336e20-4ab2-5ec4-ac5c-c436a494f198', 100001, 'b45c8351-d439-5d6b-98e9-cfe2dcc55ccb', 'websiteRootEventDeliveries.replace', 'PUT', '/internal/v3/api/drive/website_roots/{websiteRootUuid}/event_deliveries/{channelId}', 'Ensure a signed WebsiteRoot event delivery channel', 'Creates or reconciles one root-scoped Drive-to-Webserver webhook channel for a Web Node. The channel receives only typed events that affect this stable WebsiteRoot UUID. The verification token is write-only; Drive stores only its SHA-256 derived signing key.', $sdkwork_catalog$["driveInternalPublishing"]$sdkwork_catalog$::jsonb, FALSE, 50),
  ('2229b7ba-d15e-5b55-81a2-90b04ff9efc5', 100001, 'b45c8351-d439-5d6b-98e9-cfe2dcc55ccb', 'driveResources.resolve', 'POST', '/internal/v3/api/drive/resource_resolutions', 'Resolve a root-qualified Drive resource', 'Resolves an eligible file below a WebsiteRoot or RootScopeSubscription. The response contains logical Drive identity and cache validators but no object-store coordinates.', $sdkwork_catalog$["driveInternalPublishing"]$sdkwork_catalog$::jsonb, FALSE, 60),
  ('31cfc661-365a-51c4-8fde-eef032395964', 100001, 'b45c8351-d439-5d6b-98e9-cfe2dcc55ccb', 'driveResourceContent.retrieve', 'GET', '/internal/v3/api/drive/node_versions/{nodeVersionId}/content', 'Stream root-qualified immutable Drive content', 'Streams one logical node version only after re-resolving its scope and path binding. Supports one RFC 9110 byte range and ETag/date preconditions. Bucket, object key, credentials, and presigned URLs never cross this API boundary.', $sdkwork_catalog$["driveInternalPublishing"]$sdkwork_catalog$::jsonb, FALSE, 70)
